head.b:skin:
/**/
/* ==========================================================================
   BUZZSTORMNOW MASTER DESIGN SYSTEM - PIXEL-PERFECT FIGMA BLUEPRINT
   Pure Vanilla CSS - Ultra High Performance - Zero Dependencies
   ========================================================================== */

:root {
  --primary: #E94560;
  --primary-hover: #D1304B;
  --primary-light: rgba(233, 69, 96, 0.08);
  --primary-border: rgba(233, 69, 96, 0.22);
  --primary-glow: rgba(233, 69, 96, 0.35);

  --bg: #FFFFFF;
  --surface: #F7F7F8;
  --surface-card: #FFFFFF;
  --border: #E5E7EB;
  --border-subtle: #F0F0F2;

  --text-primary: #0A0A0A;
  --text-secondary: #6B7280;
  --text-muted: #9CA3AF;

  --badge-tech-bg: #EFF6FF;
  --badge-tech-text: #2563EB;
  --badge-science-bg: #FAF5FF;
  --badge-science-text: #9333EA;
  --badge-market-bg: #FFFBEB;
  --badge-market-text: #D97706;
  --badge-sports-bg: #ECFDF5;
  --badge-sports-text: #059669;

  --font-heading: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-serif: 'Lora', Georgia, serif;

  --radius-xs: 4px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -1px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -2px rgba(0, 0, 0, 0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1);

  --container-max: 1280px;
  --header-height: 64px;
}

[data-theme='dark'], body.dark {
  --bg: #0A0A0A;
  --surface: #121214;
  --surface-card: #18181B;
  --border: #27272A;
  --border-subtle: #1F1F23;

  --text-primary: #F9FAFB;
  --text-secondary: #9CA3AF;
  --text-muted: #6B7280;

  --badge-tech-bg: rgba(37, 99, 235, 0.15);
  --badge-tech-text: #60A5FA;
  --badge-science-bg: rgba(147, 51, 234, 0.15);
  --badge-science-text: #C084FC;
  --badge-market-bg: rgba(217, 119, 6, 0.15);
  --badge-market-text: #FBBF24;
  --badge-sports-bg: rgba(5, 150, 105, 0.15);
  --badge-sports-text: #34D399;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
  transition: background-color 0.2s ease, color 0.2s ease;
  padding-bottom: 64px;
}

@media (min-width: 769px) {
  body { padding-bottom: 0; }
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
button, input, select, textarea { font-family: inherit; font-size: inherit; outline: none; border: none; }

.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  vertical-align: middle;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* Layout Container */
.bzn-container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 20px;
}

@media (max-width: 640px) {
  .bzn-container { padding: 0 14px; }
}

/* Reading Progress Bar */
.bzn-reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  width: 0%;
  height: 3px;
  background: var(--primary);
  z-index: 10001;
  transition: width 0.1s linear;
}

/* Header */
.bzn-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  height: var(--header-height);
}

[data-theme='dark'] .bzn-header, body.dark .bzn-header {
  background: rgba(10, 10, 10, 0.95);
}

.bzn-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.bzn-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--text-primary);
}

.bzn-brand-icon {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--primary) 0%, #B91C1C 100%);
  color: #FFF;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px var(--primary-glow);
}

.bzn-brand span { color: var(--primary); }

.bzn-nav-desktop {
  display: flex;
  align-items: center;
  gap: 24px;
}

@media (max-width: 980px) {
  .bzn-nav-desktop { display: none; }
}

.bzn-nav-item {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 6px 0;
  position: relative;
  transition: color 0.15s ease;
}

.bzn-nav-item:hover, .bzn-nav-item.active {
  color: var(--text-primary);
}

.bzn-nav-item.active {
  color: var(--primary);
}

.bzn-header-tools {
  display: flex;
  align-items: center;
  gap: 10px;
}

.bzn-icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--surface);
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: 1px solid var(--border);
  transition: all 0.15s ease;
}

.bzn-icon-btn:hover {
  background: var(--border);
  color: var(--primary);
}

/* Language Dropdown */
.bzn-lang-wrap { position: relative; }
.bzn-lang-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  cursor: pointer;
}

.bzn-lang-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 190px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  padding: 6px;
  display: none;
  z-index: 1001;
  max-height: 300px;
  overflow-y: auto;
}

.bzn-lang-menu.open { display: block; }
.bzn-lang-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  cursor: pointer;
}
.bzn-lang-item:hover, .bzn-lang-item.selected {
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 700;
}

/* Live Wire Ribbon */
.bzn-live-wire {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 8px 0;
  font-size: 13px;
}

.bzn-live-wire-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.bzn-live-wire-left {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bzn-live-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--primary);
  color: #FFF;
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  flex-shrink: 0;
}

.bzn-radar-pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #FFF;
  box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.8);
  animation: radarPulse 1.6s infinite cubic-bezier(0.66, 0, 0, 1);
}

@keyframes radarPulse {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.8); }
  70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(255, 255, 255, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(255, 255, 255, 0); }
}

.bzn-wire-text { font-weight: 500; color: var(--text-secondary); }
.bzn-wire-link {
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 700;
  color: var(--primary);
  flex-shrink: 0;
}
.bzn-wire-link:hover { text-decoration: underline; }

/* 2-Column Hero Grid (Screen 02) */
.bzn-hero-grid {
  display: grid;
  grid-template-columns: 1.65fr 1.05fr;
  gap: 24px;
  margin-top: 24px;
  margin-bottom: 36px;
}

@media (max-width: 980px) {
  .bzn-hero-grid { grid-template-columns: 1fr; gap: 20px; }
}

/* Dark Hero Card (Exact Match to Figma SS) */
.bzn-hero-card.dark-hero {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #0A0A0A;
  color: #FFF;
  border: 1px solid #1F2937;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-md);
}

.bzn-hero-img-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: #111827;
}

.bzn-hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.bzn-hero-card:hover .bzn-hero-img { transform: scale(1.03); }

.bzn-hero-gradient-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, #0A0A0A 0%, rgba(10, 10, 10, 0.75) 50%, rgba(10, 10, 10, 0.1) 100%);
  pointer-events: none;
}

.bzn-badge-breaking {
  position: absolute;
  top: 14px;
  left: 14px;
  background: var(--primary);
  color: #FFF;
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  padding: 4px 10px;
  border-radius: var(--radius-xs);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  z-index: 2;
}

.bzn-hero-carousel-nav {
  position: absolute;
  top: 50%;
  right: 14px;
  transform: translateY(-50%);
  z-index: 3;
}

.bzn-hero-nav-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  color: #FFF;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.bzn-hero-content {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.bzn-hero-kicker {
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #60A5FA;
  margin-bottom: 8px;
}

.bzn-hero-title {
  font-family: var(--font-heading);
  font-size: 26px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: #FFFFFF;
  margin-bottom: 12px;
}

.bzn-hero-title a { color: #FFFFFF; }
.bzn-hero-title a:hover { color: #93C5FD; }

@media (max-width: 640px) {
  .bzn-hero-title { font-size: 20px; }
}

.bzn-hero-excerpt {
  font-size: 14px;
  color: #D1D5DB;
  line-height: 1.6;
  margin-bottom: 16px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.bzn-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: #9CA3AF;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 14px;
  margin-top: auto;
}

.bzn-meta-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Trending Now Panel (Screen 02) */
.bzn-trending-panel {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
}

.bzn-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.bzn-panel-title {
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
}

.bzn-panel-title .material-symbols-outlined { color: var(--primary); }

.bzn-trending-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  list-style: none;
}

.bzn-trending-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px;
  border-radius: var(--radius-md);
  transition: background 0.15s ease;
}

.bzn-trending-item:hover { background: var(--surface); }

.bzn-trending-num {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  color: #FFF;
  background: var(--primary);
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.bzn-trending-thumb {
  width: 54px;
  height: 54px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  flex-shrink: 0;
}

.bzn-trending-thumb-placeholder {
  width: 54px;
  height: 54px;
  border-radius: var(--radius-sm);
  background: var(--surface);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  flex-shrink: 0;
}

.bzn-trending-info { flex: 1; overflow: hidden; }

.bzn-trending-headline {
  font-family: var(--font-heading);
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text-primary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 4px;
}

.bzn-trending-item:hover .bzn-trending-headline { color: var(--primary); }

.bzn-trending-meta { font-size: 11px; color: var(--text-muted); }

/* Latest Stories 4-Column Grid */
.bzn-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 36px 0 20px 0;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.bzn-section-title {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 10px;
}

.bzn-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

@media (max-width: 1100px) { .bzn-grid-4 { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 768px) { .bzn-grid-4 { grid-template-columns: repeat(2, 1fr); gap: 14px; } }
@media (max-width: 480px) { .bzn-grid-4 { grid-template-columns: 1fr; } }

.bzn-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.bzn-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.bzn-card-thumb-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--surface);
}

.bzn-card-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.bzn-card:hover .bzn-card-thumb { transform: scale(1.04); }

.bzn-card-thumb-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.bzn-card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.bzn-card-pill-row { margin-bottom: 8px; }

.bzn-pill-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  background: var(--badge-tech-bg);
  color: var(--badge-tech-text);
}

.bzn-card-title {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text-primary);
  margin-bottom: 10px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.bzn-card:hover .bzn-card-title { color: var(--primary); }

.bzn-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid var(--border-subtle);
}

/* Newsletter Banner (Screen 14) */
.bzn-newsletter-banner {
  background: linear-gradient(135deg, var(--surface) 0%, var(--surface-card) 100%);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 40px 32px;
  margin: 48px 0;
  text-align: center;
  box-shadow: var(--shadow-sm);
}

.bzn-newsletter-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--primary-light);
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
}

.bzn-newsletter-icon .material-symbols-outlined { font-size: 28px; }

.bzn-newsletter-title {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 8px;
}

.bzn-newsletter-desc {
  font-size: 14px;
  color: var(--text-secondary);
  max-width: 520px;
  margin: 0 auto 20px auto;
}

.bzn-newsletter-form {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  max-width: 480px;
  margin: 0 auto;
}

@media (max-width: 560px) {
  .bzn-newsletter-form { flex-direction: column; width: 100%; }
}

.bzn-input {
  flex: 1;
  width: 100%;
  height: 44px;
  padding: 0 16px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  color: var(--text-primary);
  font-size: 14px;
}

.bzn-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-light);
}

.bzn-btn-primary {
  height: 44px;
  padding: 0 24px;
  background: var(--primary);
  color: #FFF;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
  box-shadow: 0 2px 8px var(--primary-glow);
  transition: all 0.15s ease;
}

.bzn-btn-primary:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
}

.bzn-btn-secondary {
  height: 40px;
  padding: 0 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}

.bzn-btn-secondary:hover {
  background: var(--border);
  color: var(--primary);
}

.bzn-newsletter-trust {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

/* Category Page Header (Screen 04) */
.bzn-category-header {
  margin-top: 28px;
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bzn-category-title {
  font-family: var(--font-heading);
  font-size: 34px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.025em;
  color: var(--text-primary);
  margin: 0;
  display: block;
}

.bzn-category-subtitle {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.55;
  max-width: 720px;
  margin: 0;
  display: block;
}

.bzn-footer-links a.active {
  color: var(--primary) !important;
  font-weight: 700;
}

.bzn-filter-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.bzn-filter-pill {
  padding: 6px 14px;
  border-radius: var(--radius-full);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  transition: all 0.15s ease;
}

.bzn-filter-pill:hover, .bzn-filter-pill.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #FFF;
}

/* Article Page Layout (Screens 07 & 08) */
.bzn-article-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 36px;
  margin-top: 24px;
}

@media (max-width: 980px) {
  .bzn-article-layout { grid-template-columns: 1fr; gap: 28px; }
}

.bzn-breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.bzn-article-kicker {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 8px;
}

.bzn-article-title {
  font-family: var(--font-heading);
  font-size: 34px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.025em;
  margin-bottom: 14px;
}

@media (max-width: 640px) { .bzn-article-title { font-size: 24px; } }

.bzn-article-dek {
  font-size: 17px;
  line-height: 1.55;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.bzn-author-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 12px;
}

.bzn-author-info { display: flex; align-items: center; gap: 12px; }

.bzn-author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--surface);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
}

.bzn-author-name {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 700;
}

.bzn-author-meta { font-size: 12px; color: var(--text-muted); }

.bzn-action-tools { display: flex; align-items: center; gap: 8px; }

.bzn-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: var(--radius-full);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.bzn-action-btn:hover { background: var(--border); color: var(--primary); }
.bzn-action-btn.saved { color: var(--primary); background: var(--primary-light); }

.bzn-article-hero-wrap {
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 24px;
  background: var(--surface);
  border: 1px solid var(--border);
}

.bzn-article-hero-img { width: 100%; height: 100%; object-fit: cover; }

/* Key Takeaways Bento Box (Screen 07) */
.bzn-takeaways-box {
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid var(--primary);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 28px;
}

.bzn-takeaways-title {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.bzn-takeaways-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 14px;
  color: var(--text-secondary);
}

.bzn-takeaways-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  line-height: 1.5;
}

.bzn-takeaways-item .material-symbols-outlined {
  color: var(--primary);
  font-size: 18px;
  margin-top: 2px;
  flex-shrink: 0;
}

/* Audio Player Card (Screens 07 & 10) */
.bzn-audio-box {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px 20px;
  margin-bottom: 28px;
  box-shadow: var(--shadow-sm);
}

.bzn-audio-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.bzn-audio-heading {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}

.bzn-speed-pills { display: flex; align-items: center; gap: 4px; }
.bzn-speed-btn {
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
}

.bzn-speed-btn.active, .bzn-speed-btn:hover {
  background: var(--primary);
  color: #FFF;
  border-color: var(--primary);
}

.bzn-audio-controls { display: flex; align-items: center; gap: 14px; }

.bzn-play-btn {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--primary);
  color: #FFF;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  box-shadow: 0 2px 8px var(--primary-glow);
}

.bzn-scrubber-track {
  flex: 1;
  height: 6px;
  background: var(--border);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  overflow: hidden;
}

.bzn-scrubber-fill {
  height: 100%;
  width: 0%;
  background: var(--primary);
  border-radius: var(--radius-full);
  transition: width 0.1s linear;
}

.bzn-time-display { font-size: 12px; font-weight: 600; color: var(--text-muted); min-width: 32px; }

/* Article Content */
.bzn-article-content {
  font-size: 18px;
  line-height: 1.75;
  color: var(--text-primary);
  max-width: 760px;
}

.bzn-article-content p { margin-bottom: 22px; }
.bzn-article-content h2 { font-family: var(--font-heading); font-size: 24px; font-weight: 800; margin: 36px 0 16px 0; }
.bzn-article-content h3 { font-family: var(--font-heading); font-size: 20px; font-weight: 700; margin: 28px 0 12px 0; }
.bzn-article-content blockquote {
  border-left: 3px solid var(--primary);
  padding: 12px 20px;
  margin: 24px 0;
  background: var(--surface);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  font-style: italic;
  color: var(--text-secondary);
}

.bzn-tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 32px 0;
  padding-top: 20px;
  border-top: 1px solid var(--border);
}

.bzn-tag-pill {
  padding: 4px 12px;
  border-radius: var(--radius-full);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.bzn-tag-pill:hover {
  background: var(--primary-light);
  color: var(--primary);
}

/* Sidebar Box (Right Column) */
.bzn-sidebar-box {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
}

.bzn-sidebar-title {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 8px;
}

.bzn-related-list { list-style: none; display: flex; flex-direction: column; gap: 14px; }
.bzn-related-item { display: flex; align-items: center; gap: 12px; }

.bzn-related-thumb {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  flex-shrink: 0;
}

.bzn-related-title {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.bzn-related-title:hover { color: var(--primary); }
.bzn-related-date { font-size: 11px; color: var(--text-muted); }

/* Static Page Card (Screens 16-18) */
.bzn-page-card {
  max-width: 800px;
  margin: 32px auto;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 40px;
}

/* 404 Error Card (Screen 19) */
.bzn-error-card {
  text-align: center;
  padding: 80px 20px;
  max-width: 600px;
  margin: 0 auto;
}

.bzn-error-code {
  font-family: var(--font-heading);
  font-size: 96px;
  font-weight: 900;
  color: var(--primary);
  line-height: 1;
}

.bzn-error-title {
  font-family: var(--font-heading);
  font-size: 26px;
  font-weight: 800;
  margin: 16px 0 8px 0;
}

.bzn-error-desc {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

.bzn-error-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Pagination */
.bzn-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 40px 0;
}

/* Search Overlay (Screen 12) */
.bzn-search-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 11000;
  display: none;
  align-items: flex-start;
  justify-content: center;
  padding: 80px 20px;
}

.bzn-search-overlay.open { display: flex; }

.bzn-search-modal {
  width: 100%;
  max-width: 600px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 24px;
  box-shadow: var(--shadow-xl);
  animation: modalSlide 0.25s ease;
}

@keyframes modalSlide {
  from { transform: translateY(-20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.bzn-search-input-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 20px;
}

.bzn-search-input {
  flex: 1;
  background: transparent;
  color: var(--text-primary);
  font-size: 16px;
}

.bzn-pills-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }

.bzn-search-pill {
  padding: 6px 12px;
  border-radius: var(--radius-full);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
}

.bzn-search-pill:hover {
  background: var(--primary-light);
  color: var(--primary);
  border-color: var(--primary-border);
}

/* Reading Tools Modal (Screen 09) */
.bzn-reading-modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(4px);
  z-index: 11000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.bzn-reading-modal.open { display: flex; }

.bzn-reading-box {
  width: 100%;
  max-width: 440px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 24px;
  box-shadow: var(--shadow-xl);
}

.bzn-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.bzn-modal-title { font-family: var(--font-heading); font-size: 18px; font-weight: 800; }
.bzn-tool-group { margin-bottom: 18px; }
.bzn-tool-label {
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.bzn-btn-segmented { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }

.bzn-segment-btn {
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--surface);
  border: 1px solid var(--border);
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  text-align: center;
}

.bzn-segment-btn.active, .bzn-segment-btn:hover {
  background: var(--primary);
  color: #FFF;
  border-color: var(--primary);
}

/* Toast Notifications (Screen 25) */
.bzn-toast-container {
  position: fixed;
  bottom: 80px;
  right: 20px;
  z-index: 12000;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}

@media (max-width: 768px) {
  .bzn-toast-container { bottom: 74px; right: 14px; left: 14px; }
}

.bzn-toast {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-left: 4px solid var(--primary);
  color: var(--text-primary);
  padding: 12px 18px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
  animation: toastIn 0.3s ease;
  transition: opacity 0.3s ease;
}

@keyframes toastIn {
  from { transform: translateY(10px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* Mobile Bottom Navigation (Screen 26) */
.bzn-mobile-bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60px;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-top: 1px solid var(--border);
  display: none;
  align-items: center;
  justify-content: space-around;
  z-index: 9999;
}

[data-theme='dark'] .bzn-mobile-bottom-nav, body.dark .bzn-mobile-bottom-nav {
  background: rgba(10, 10, 10, 0.96);
}

@media (max-width: 768px) {
  .bzn-mobile-bottom-nav { display: flex; }
}

.bzn-bottom-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  flex: 1;
  height: 100%;
}

.bzn-bottom-nav-item.active, .bzn-bottom-nav-item:hover { color: var(--primary); }
.bzn-bottom-nav-item .material-symbols-outlined { font-size: 22px; }

/* Off-Canvas Mobile Drawer (Screen 22) */
.bzn-mobile-drawer {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(4px);
  z-index: 10500;
  display: none;
}

.bzn-mobile-drawer.open { display: block; }

.bzn-drawer-panel {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 82%;
  max-width: 320px;
  background: var(--surface-card);
  padding: 24px;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-xl);
  animation: drawerSlide 0.3s ease;
}

@keyframes drawerSlide {
  from { transform: translateX(-100%); }
  to { transform: translateX(0); }
}

.bzn-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.bzn-drawer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 16px;
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
}

.bzn-drawer-links a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  color: var(--text-primary);
}

.bzn-drawer-links a:hover { color: var(--primary); }

/* Footer */
.bzn-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding: 48px 0 24px 0;
  margin-top: 60px;
  font-size: 14px;
}

.bzn-footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 36px;
  margin-bottom: 40px;
}

@media (max-width: 768px) {
  .bzn-footer-grid { grid-template-columns: 1fr; gap: 24px; }
}

.bzn-footer-brand p {
  color: var(--text-secondary);
  font-size: 13px;
  margin-top: 12px;
  max-width: 320px;
}

.bzn-footer-heading {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}

.bzn-footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: var(--text-secondary);
  font-size: 13px;
}

.bzn-footer-links a:hover { color: var(--primary); }

.bzn-footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  text-align: center;
  font-size: 12px;
  color: var(--text-muted);
}

/* ---- Back to top ---- */
.bzn-back-top{position:fixed;right:18px;bottom:78px;width:42px;height:42px;border-radius:50%;background:var(--primary);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 4px 14px var(--primary-glow);opacity:0;visibility:hidden;transform:translateY(10px);transition:all .25s ease;z-index:9000}
.bzn-back-top.show{opacity:1;visibility:visible;transform:none}
@media(min-width:769px){.bzn-back-top{bottom:24px}}
/* ---- Hamburger ---- */
.bzn-menu-toggle{display:none}
@media(max-width:980px){.bzn-menu-toggle{display:inline-flex}}
@media(max-width:560px){.bzn-lang-btn #bznCurrentLang{display:none}.bzn-lang-btn{padding:6px 10px}}
/* ---- Category pill colours ---- */
.bzn-pill-badge.is-sci{background:var(--badge-science-bg);color:var(--badge-science-text)}
.bzn-pill-badge.is-biz{background:var(--badge-market-bg);color:var(--badge-market-text)}
.bzn-pill-badge.is-sport{background:var(--badge-sports-bg);color:var(--badge-sports-text)}
.bzn-pill-badge.is-hot{background:var(--primary-light);color:var(--primary)}
/* ---- Static pages / post body ---- */
.bzn-page-card h1,.bzn-page-card h2,.bzn-page-card h3{font-family:var(--font-heading)}
.bzn-article-content ul,.bzn-article-content ol{margin:0 0 22px 22px}
.bzn-article-content a{color:var(--primary);text-decoration:underline}
.bzn-article-content img,.bzn-article-content iframe,.bzn-article-content table{max-width:100%}
.bzn-article-content table{display:block;overflow-x:auto}
/* ---- Comments (Blogger widget) ---- */
.bzn-comments-wrapper{margin-top:40px;padding-top:24px;border-top:1px solid var(--border)}
.bzn-comments-wrapper iframe{width:100%;border:0}
.bzn-comments-wrapper .comments .comment-block,.bzn-comments-wrapper .comment-content{font-size:14px;color:var(--text-secondary)}
/* ---- Safety ---- */
.bzn-container,.bzn-article-main,.bzn-article-sidebar{min-width:0}
.bzn-hero-grid>*{min-width:0}
.bzn-page-body{min-height:60vh}

.bzn-hero-fallback{width:100%;height:100%;background:linear-gradient(135deg,#1F2937,#0A0A0A);display:flex;align-items:center;justify-content:center;color:#6B7280}
.bzn-article-header{margin-bottom:8px}
.bzn-related-info{min-width:0;display:flex;flex-direction:column;gap:2px}
.bzn-sidebar-newsletter{background:var(--surface);border-color:var(--primary-border);text-align:center}
@media(min-width:981px){.bzn-article-sidebar{position:sticky;top:calc(var(--header-height) + 16px);align-self:start}}

.bzn-empty-state{text-align:center;padding:64px 20px;max-width:520px;margin:24px auto}
.bzn-empty-state[hidden]{display:none}
.bzn-empty-icon{width:64px;height:64px;border-radius:50%;background:var(--primary-light);color:var(--primary);display:inline-flex;align-items:center;justify-content:center;margin-bottom:14px}
.bzn-empty-icon .material-symbols-outlined{font-size:32px}
.bzn-empty-title{font-family:var(--font-heading);font-size:22px;font-weight:800;margin-bottom:6px}
.bzn-empty-desc{font-size:14px;color:var(--text-secondary);margin-bottom:20px}

/* Google Website Translator Silent Integration */
#google_translate_element {
  display: none !important;
  visibility: hidden !important;
  position: absolute !important;
  top: -9999px !important;
  left: -9999px !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
}

.goog-te-banner-frame,
.goog-te-banner-frame.skiptranslate,
iframe.goog-te-banner-frame {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  width: 0 !important;
}

body {
  top: 0px !important;
  position: static !important;
}

#goog-gt-tt,
.goog-te-balloon-frame,
.goog-tooltip,
.goog-tooltip:hover {
  display: none !important;
  visibility: hidden !important;
}

.goog-text-highlight {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

font {
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
}

.notranslate,
[translate="no"] {
  -webkit-font-smoothing: antialiased;
}


/* ==========================================================================
   ARTICLE PAGE MASTER REDESIGN & SIDEBAR ENHANCEMENTS
   Exact benchmark to Screens 01, 02, 03
   ========================================================================== */

/* Reading Styles Custom Variables */
:root {
  --article-reading-font: var(--font-body);
  --article-reading-size: 18px;
  --article-reading-line: 1.8;
  --article-reading-width: 760px;
}

.bzn-article-content,
.bzn-article-content p,
.bzn-article-content span,
.bzn-article-content div,
.bzn-article-content li {
  font-family: var(--article-reading-font) !important;
  font-size: var(--article-reading-size) !important;
  line-height: var(--article-reading-line) !important;
}

.bzn-article-content {
  max-width: var(--article-reading-width) !important;
}

/* Full-Width Hero Header */
.bzn-article-hero-header {
  padding: 24px 0 20px 0;
  margin-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.bzn-article-prehead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
}

.bzn-header-badges {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.bzn-badge-alert {
  background: #b91c1c;
  color: #fff;
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: var(--radius-xs);
  letter-spacing: 0.05em;
  display: inline-flex;
  align-items: center;
}

.bzn-badge-topic {
  background: #1e3a8a;
  color: #93c5fd;
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-xs);
  letter-spacing: 0.03em;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
}

.bzn-article-hero-header .bzn-article-title {
  font-family: var(--font-heading);
  font-size: 36px;
  font-weight: 900;
  line-height: 1.25;
  color: var(--text-primary);
  margin: 0 0 12px 0;
  letter-spacing: -0.02em;
}

@media(max-width: 768px) {
  .bzn-article-hero-header .bzn-article-title {
    font-size: 26px;
  }
}

.bzn-article-hero-header .bzn-article-dek {
  font-size: 18px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 0 0 20px 0;
}

/* Author Row & Tools */
.bzn-author-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding: 12px 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin-bottom: 20px;
}

.bzn-author-avatar {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: #1e3a8a;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  font-family: var(--font-heading);
  letter-spacing: 0.05em;
  flex-shrink: 0;
}

.bzn-verified-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #10b981;
  font-weight: 600;
  font-size: 12px;
  margin-left: 6px;
}

.bzn-verified-tag .material-symbols-outlined {
  font-size: 15px;
}

.bzn-action-tools {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bzn-action-icon-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface-card);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.15s ease;
}

.bzn-action-icon-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.bzn-action-icon-btn.saved {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* Full-Width Audio Player Bar (Screen 02) */
.bzn-audio-full {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 14px 20px;
  background: #0f172a;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  color: #fff;
  margin-bottom: 28px;
  flex-wrap: wrap;
}

.bzn-audio-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

.bzn-audio-label-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bzn-audio-primary {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 800;
  color: #fff;
}

.bzn-badge-audio-hd {
  background: #0284c7;
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: var(--radius-xs);
  letter-spacing: 0.05em;
}

.bzn-audio-secondary {
  font-size: 12px;
  color: #94a3b8;
}

.bzn-audio-center {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 200px;
  max-width: 480px;
}

.bzn-audio-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bzn-focus-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255,255,255,0.25);
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.bzn-focus-btn:hover {
  background: rgba(255,255,255,0.2);
  border-color: #fff;
}

/* Sticky Mini Audio Bar */
.bzn-sticky-audio-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: #0f172a;
  border-top: 1px solid rgba(255,255,255,0.15);
  box-shadow: 0 -4px 25px rgba(0,0,0,0.4);
  z-index: 1000;
  padding: 10px 0;
  display: none;
  color: #fff;
}

@media(max-width: 768px) {
  .bzn-sticky-audio-bar {
    bottom: 58px;
  }
}

.bzn-sticky-audio-bar.visible {
  display: block;
  animation: slideUpAudio 0.25s ease;
}

@keyframes slideUpAudio {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

.bzn-sticky-audio-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.bzn-sticky-audio-meta {
  flex: 1;
  min-width: 0;
}

.bzn-sticky-audio-title {
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bzn-sticky-audio-sub {
  font-size: 11px;
  color: #94a3b8;
}

.bzn-sticky-scrubber {
  width: 160px;
  height: 6px;
  background: rgba(255,255,255,0.2);
  border-radius: var(--radius-full);
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.bzn-sticky-scrubber-fill {
  height: 100%;
  width: 0%;
  background: var(--primary);
  border-radius: var(--radius-full);
}

/* Impact Breakdown Card (Screen 02) */
.bzn-impact-breakdown-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
}

.bzn-impact-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.bzn-impact-kicker {
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.bzn-impact-title {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 900;
  color: var(--text-primary);
  margin: 0;
}

.bzn-impact-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
}

.bzn-dot-active {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #0284c7;
}

.bzn-delta-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}

@media(max-width: 640px) {
  .bzn-delta-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.bzn-delta-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 12px 14px;
}

.bzn-delta-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.03em;
  margin-bottom: 4px;
}

.bzn-delta-val {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 900;
  color: var(--text-primary);
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.bzn-delta-val.positive { color: #10b981; }
.bzn-delta-val.negative { color: #ef4444; }

.bzn-delta-sub {
  font-size: 11px;
  font-weight: 700;
}

.bzn-delta-sub.positive { color: #10b981; }
.bzn-delta-badge {
  font-size: 11px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: var(--radius-xs);
  background: rgba(16,185,129,0.15);
}

.bzn-delta-badge.negative {
  background: rgba(239,68,68,0.15);
}

.bzn-delta-note {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 4px;
}

.bzn-impact-progress-wrap {
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.bzn-progress-labels {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.bzn-impact-progress-bar {
  height: 7px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: 8px;
}

.bzn-impact-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #0284c7, #2563eb);
  border-radius: var(--radius-full);
}

.bzn-impact-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

/* Executive Brief Bento Box (Screen 02) */
.bzn-executive-brief-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px 22px;
  margin-bottom: 28px;
}

.bzn-brief-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.bzn-brief-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bzn-brief-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #0284c7;
}

.bzn-brief-title {
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--primary);
}

.bzn-brief-timing {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
}

.bzn-brief-lead {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 14px;
}

.bzn-brief-list {
  list-style: none;
  padding: 0;
  margin: 0 0 16px 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.bzn-brief-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-primary);
}

.bzn-check-icon {
  color: #0284c7;
  font-size: 18px;
  flex-shrink: 0;
  margin-top: 1px;
}

.bzn-brief-jump {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 700;
  color: var(--primary);
  text-decoration: none;
}

.bzn-brief-jump:hover {
  text-decoration: underline;
}

/* Section Paradigm & Drop Cap */
.bzn-section-paradigm {
  margin: 28px 0 16px 0;
}

.bzn-paradigm-marker {
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: 0.05em;
  display: block;
  margin-bottom: 4px;
}

.bzn-paradigm-title {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 900;
  color: var(--text-primary);
  margin: 0;
}

.bzn-article-content > p:first-of-type::first-letter {
  font-family: var(--font-heading);
  font-size: 3.6em;
  float: left;
  line-height: 0.8;
  margin-right: 12px;
  margin-top: 4px;
  font-weight: 900;
  color: var(--primary);
}

/* Real-Time Live Market Report Chart Card (Screen 02) */
.bzn-market-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 18px 20px;
  margin-bottom: 22px;
  box-shadow: var(--shadow-sm);
}

.bzn-market-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.bzn-market-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
}

.bzn-live-pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #0284c7;
  animation: pulseGlow 1.8s infinite;
}

@keyframes pulseGlow {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(2, 132, 199, 0.7); }
  70% { transform: scale(1); box-shadow: 0 0 0 6px rgba(2, 132, 199, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(2, 132, 199, 0); }
}

.bzn-badge-realtime {
  font-family: var(--font-heading);
  font-size: 10px;
  font-weight: 800;
  color: #0284c7;
  background: rgba(2, 132, 199, 0.1);
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  letter-spacing: 0.05em;
}

.bzn-market-price-row {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 4px;
}

.bzn-market-price {
  font-family: var(--font-heading);
  font-size: 28px;
  font-weight: 900;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.bzn-market-change {
  font-size: 14px;
  font-weight: 800;
  transition: all 0.3s ease;
}

.bzn-market-change.positive { color: #10b981; }
.bzn-market-change.negative { color: #ef4444; }

.bzn-market-range {
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.bzn-market-stat-block {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  margin-bottom: 12px;
}

.bzn-market-stat-head {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.bzn-market-stat-head strong {
  color: var(--text-primary);
}

.bzn-progress-bar {
  height: 6px;
  background: var(--surface-card);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: 6px;
}

.bzn-progress-fill {
  height: 100%;
  background: #0284c7;
  border-radius: var(--radius-full);
  transition: width 0.5s ease;
}

.bzn-market-stat-sub {
  font-size: 11px;
  color: var(--text-muted);
}

.bzn-market-metrics-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.bzn-metric-cell {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
}

.bzn-metric-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.bzn-metric-val {
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  color: var(--text-primary);
}

/* Sidebar Section Headers */
.bzn-sidebar-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.bzn-kicker-pulse {
  font-family: var(--font-heading);
  font-size: 10px;
  font-weight: 800;
  color: #b91c1c;
  letter-spacing: 0.05em;
}

.bzn-indexed-tag {
  font-family: var(--font-heading);
  font-size: 10px;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

/* Curated Topic Radar (Screen 01) */
.bzn-topic-radar-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 18px;
}

.bzn-radar-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-xs);
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
  transition: all 0.15s ease;
}

.bzn-radar-tag:hover {
  background: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
}

.bzn-tag-count {
  font-size: 10px;
  color: #0284c7;
  font-weight: 800;
}

.bzn-discover-channels-wrap {
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.bzn-channels-label {
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  margin-bottom: 10px;
}

.bzn-channel-search-box {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  margin-bottom: 10px;
}

.bzn-channel-search-box .material-symbols-outlined {
  font-size: 16px;
  color: var(--text-muted);
}

.bzn-channel-search-input {
  border: none;
  background: transparent;
  width: 100%;
  font-size: 12px;
  color: var(--text-primary);
  outline: none;
}

.bzn-channel-cards-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.bzn-channel-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
  transition: all 0.15s ease;
}

.bzn-channel-card:hover {
  border-color: var(--primary);
  background: var(--primary-light);
  color: var(--primary);
}

.bzn-channel-card .material-symbols-outlined {
  font-size: 14px;
  color: var(--text-muted);
}

/* Contact Newsroom Card (Screen 01) */
.bzn-newsroom-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  margin-bottom: 22px;
}

.bzn-newsroom-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.bzn-newsroom-head h4 {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 900;
  color: var(--text-primary);
  margin: 0;
  letter-spacing: 0.03em;
}

.bzn-newsroom-desc {
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-secondary);
  margin-bottom: 14px;
}

.bzn-field-group {
  margin-bottom: 10px;
}

.bzn-field-label {
  display: block;
  font-size: 10px;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.bzn-newsroom-form .bzn-input {
  width: 100%;
  font-size: 12px;
  padding: 8px 10px;
  border-radius: var(--radius-xs);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-primary);
  box-sizing: border-box;
}

.bzn-newsroom-form .bzn-textarea {
  resize: vertical;
  min-height: 60px;
  font-family: inherit;
}

.bzn-newsroom-submit-btn {
  width: 100%;
  height: 40px;
  background: #0f172a;
  color: #fff;
  border: none;
  border-radius: var(--radius-xs);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  margin-top: 6px;
}

.bzn-newsroom-submit-btn:hover {
  background: #1e293b;
}

/* Sidebar Ad Slot */
.bzn-sidebar-ad-slot {
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: var(--radius-md);
  padding: 12px;
  text-align: center;
  margin-bottom: 22px;
}

.bzn-ad-label {
  font-size: 10px;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  margin-bottom: 8px;
}

/* Post-Article Share Bar (Screen 03) */
.bzn-post-share-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin: 28px 0;
  flex-wrap: wrap;
  gap: 12px;
}

.bzn-share-stats {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: 0.03em;
}

.bzn-share-actions-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.bzn-share-dispatch-btn {
  background: #1d4ed8;
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  padding: 8px 16px;
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.bzn-share-dispatch-btn:hover {
  background: #1e40af;
}

.bzn-print-btn {
  background: transparent;
  color: var(--text-secondary);
  border: none;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  padding: 6px 10px;
}

.bzn-print-btn:hover {
  color: var(--text-primary);
  text-decoration: underline;
}

/* Accredited Bureau Box (Screen 03) */
.bzn-bureau-card {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 18px 22px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 28px;
}

.bzn-bureau-badge-avatar {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: #1e40af;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0.05em;
  flex-shrink: 0;
}

.bzn-bureau-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.bzn-bureau-title {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
}

.bzn-badge-accredited {
  font-family: var(--font-heading);
  font-size: 10px;
  font-weight: 800;
  color: #1d4ed8;
  background: rgba(29, 78, 216, 0.1);
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  letter-spacing: 0.05em;
}

.bzn-bureau-desc {
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-secondary);
  margin: 0;
}

/* Newer & Older Dispatch Navigation (Screen 03) */
.bzn-dispatch-nav {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin: 32px 0;
}

@media(max-width: 640px) {
  .bzn-dispatch-nav {
    grid-template-columns: 1fr;
  }
}

.bzn-dispatch-card {
  padding: 16px 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  text-decoration: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: all 0.2s ease;
}

.bzn-dispatch-card:hover {
  border-color: var(--primary);
  background: var(--surface-card);
}

.bzn-older-dispatch {
  text-align: right;
}

.bzn-nav-kicker {
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: 0.05em;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.bzn-older-dispatch .bzn-nav-kicker {
  justify-content: flex-end;
}

.bzn-nav-title {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 800;
  line-height: 1.4;
  color: var(--text-primary);
}

/* Market Desk Discussion (Screen 03) */
.bzn-discussion-section {
  margin-top: 36px;
  padding-top: 24px;
  border-top: 1px solid var(--border);
}

.bzn-discussion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
}

.bzn-discussion-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
}

.bzn-discussion-badge {
  font-size: 12px;
  font-weight: 700;
  color: #10b981;
}

.bzn-comment-compose-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 18px 20px;
  margin-bottom: 22px;
}

.bzn-compose-label {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 10px;
}

.bzn-compose-input {
  width: 100%;
  border: 1px solid var(--border);
  background: var(--surface-card);
  color: var(--text-primary);
  border-radius: var(--radius-sm);
  padding: 12px;
  font-family: inherit;
  font-size: 14px;
  line-height: 1.5;
  resize: vertical;
  box-sizing: border-box;
  outline: none;
}

.bzn-compose-input:focus {
  border-color: var(--primary);
}

.bzn-compose-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
  flex-wrap: wrap;
  gap: 10px;
}

.bzn-compliance-text {
  font-size: 12px;
  color: var(--text-muted);
}

.bzn-comment-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  margin-bottom: 14px;
}

.bzn-comment-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.bzn-comment-author-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-primary);
}

.bzn-badge-inst {
  font-family: var(--font-heading);
  font-size: 10px;
  font-weight: 800;
  background: rgba(37,99,235,0.15);
  color: #2563eb;
  padding: 2px 6px;
  border-radius: var(--radius-xs);
}

.bzn-badge-comm {
  font-family: var(--font-heading);
  font-size: 10px;
  font-weight: 800;
  background: rgba(16,185,129,0.15);
  color: #10b981;
  padding: 2px 6px;
  border-radius: var(--radius-xs);
}

.bzn-comment-time {
  font-size: 12px;
  color: var(--text-muted);
}

.bzn-comment-body {
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 0;
}

/* Bookmarks Saved Modal */
.bzn-bookmarks-box {
  max-width: 600px;
  width: 90%;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  padding: 20px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
}

.bzn-bookmarks-body {
  overflow-y: auto;
  max-height: 60vh;
  margin-top: 14px;
}

.bzn-saved-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px;
  border-bottom: 1px solid var(--border);
  gap: 12px;
}

.bzn-saved-info {
  flex: 1;
  min-width: 0;
}

.bzn-saved-title {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
  display: block;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bzn-saved-title:hover {
  color: var(--primary);
}

.bzn-saved-date {
  font-size: 11px;
  color: var(--text-muted);
}

.bzn-saved-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bzn-bookmarks-empty {
  text-align: center;
  padding: 40px 20px;
  color: var(--text-muted);
}

/* Reader Mode (Focus Mode) */
body.bzn-reader-mode-active .bzn-header,
body.bzn-reader-mode-active .bzn-live-wire,
body.bzn-reader-mode-active .bzn-article-sidebar,
body.bzn-reader-mode-active .bzn-footer,
body.bzn-reader-mode-active .bzn-ad-banner,
body.bzn-reader-mode-active .bzn-mobile-bottom-nav,
body.bzn-reader-mode-active .bzn-newsroom-card {
  display: none !important;
}

body.bzn-reader-mode-active .bzn-article-layout {
  display: block !important;
  max-width: 820px !important;
  margin: 0 auto !important;
  padding: 30px 20px 80px 20px !important;
}

body.bzn-reader-mode-active .bzn-article-main {
  max-width: 100% !important;
}

.bzn-reader-mode-bar {
  position: fixed;
  top: 16px;
  right: 16px;
  z-index: 99999;
  display: none;
  align-items: center;
  gap: 10px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-xl);
}

body.bzn-reader-mode-active .bzn-reader-mode-bar {
  display: flex !important;
}

/* Print CSS */
@media print {
  .bzn-header,
  .bzn-live-wire,
  .bzn-article-sidebar,
  .bzn-footer,
  .bzn-ad-banner,
  .bzn-sticky-audio-bar,
  .bzn-action-tools,
  .bzn-audio-box,
  .bzn-discussion-section,
  .bzn-dispatch-nav,
  .bzn-toast-container,
  .bzn-mobile-bottom-nav,
  .bzn-newsroom-card,
  .bzn-bookmarks-trigger {
    display: none !important;
  }
  body, .bzn-article-layout, .bzn-article-main {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    color: #000 !important;
    background: #fff !important;
  }
  .bzn-article-title {
    font-size: 26pt !important;
    color: #000 !important;
  }
}

/**/

body.script:
//
/* ==========================================================================
   BUZZSTORMNOW MASTER CLIENT ENGINE
   Zero Dependencies, Native Performance, 100% Error-Free
   ========================================================================== */

/* 1. Dynamic Copyright Year */
(function() {
  var el = document.getElementById('copyrightYear');
  if (el) {
    var cur = new Date().getFullYear();
    el.textContent = cur >= 2026 ? cur : '2026';
  }
})();

/* 2. Dark / Light Mode System */
function initTheme() {
  var saved = localStorage.getItem('bzn_theme');
  if (saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
    document.documentElement.setAttribute('data-theme', 'dark');
    document.body.classList.add('dark');
    updateThemeIcon(true);
  } else {
    document.documentElement.setAttribute('data-theme', 'light');
    document.body.classList.remove('dark');
    updateThemeIcon(false);
  }
}

function toggleTheme() {
  var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  if (isDark) {
    document.documentElement.setAttribute('data-theme', 'light');
    document.body.classList.remove('dark');
    localStorage.setItem('bzn_theme', 'light');
    updateThemeIcon(false);
    showToast('Switched to Light mode');
  } else {
    document.documentElement.setAttribute('data-theme', 'dark');
    document.body.classList.add('dark');
    localStorage.setItem('bzn_theme', 'dark');
    updateThemeIcon(true);
    showToast('Switched to Dark mode');
  }
}

function updateThemeIcon(isDark) {
  var icon = document.getElementById('bznThemeIcon');
  if (icon) icon.textContent = isDark ? 'light_mode' : 'dark_mode';
}
initTheme();

/* 3. Reading Progress Bar */
window.addEventListener('scroll', function() {
  var bar = document.getElementById('bznReadingProgress');
  if (!bar) return;
  var doc = document.documentElement;
  var scrollTop = window.pageYOffset || doc.scrollTop;
  var scrollHeight = doc.scrollHeight - doc.clientHeight;
  if (scrollHeight > 0) {
    var pct = Math.min(100, Math.max(0, (scrollTop / scrollHeight) * 100));
    bar.style.width = pct + '%';
  }
});

/* 4. Search Overlay & Ctrl+K Shortcut */
function openSearchModal() {
  var overlay = document.getElementById('bznSearchOverlay');
  if (overlay) {
    overlay.classList.add('open');
    var input = document.getElementById('bznSearchModalInput');
    if (input) setTimeout(function() { input.focus(); }, 100);
  }
}

function closeSearchModal() {
  var overlay = document.getElementById('bznSearchOverlay');
  if (overlay) overlay.classList.remove('open');
}

function quickSearch(term) {
  var input = document.getElementById('bznSearchModalInput');
  if (input) {
    input.value = term;
    input.closest('form').submit();
  }
}

window.addEventListener('keydown', function(e) {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
    e.preventDefault();
    openSearchModal();
  }
  if (e.key === 'Escape') {
    closeSearchModal();
    closeReadingModal();
    closeDrawer();
  }
});

/* 5. Mobile Drawer */
function openDrawer() {
  var d = document.getElementById('bznMobileDrawer');
  if (d) d.classList.add('open');
}

function closeDrawer() {
  var d = document.getElementById('bznMobileDrawer');
  if (d) d.classList.remove('open');
}

/* 6. Language Dropdown & Google Translate Integration */
function toggleLangMenu() {
  var m = document.getElementById('bznLangMenu');
  if (m) m.classList.toggle('open');
}

document.addEventListener('click', function(e) {
  var wrap = document.querySelector('.bzn-lang-wrap');
  var menu = document.getElementById('bznLangMenu');
  if (wrap && menu && !wrap.contains(e.target)) {
    menu.classList.remove('open');
  }
});

var BZN_LANG_NAMES = {
  'en': 'English',
  'hi': 'Hindi',
  'mr': 'Marathi',
  'gu': 'Gujarati',
  'bn': 'Bengali',
  'ta': 'Tamil',
  'te': 'Telugu',
  'kn': 'Kannada',
  'ml': 'Malayalam',
  'ar': 'Arabic',
  'ja': 'Japanese',
  'ko': 'Korean'
};

function setLanguage(code, name, el) {
  var cur = document.getElementById('bznCurrentLang');
  if (cur) cur.textContent = name;
  var items = document.querySelectorAll('.bzn-lang-item');
  items.forEach(function(i) {
    i.classList.remove('selected');
    var chk = i.querySelector('.material-symbols-outlined');
    if (chk) chk.remove();
  });
  if (el) {
    el.classList.add('selected');
    var chk = document.createElement('span');
    chk.className = 'material-symbols-outlined notranslate';
    chk.setAttribute('translate', 'no');
    chk.textContent = 'check';
    el.appendChild(chk);
  }
  toggleLangMenu();

  var domain = window.location.hostname;

  if (code === 'en') {
    showToast('Resetting to English...');
    // Clear cookies across root, subdomains, and host
    var exp = '=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;';
    document.cookie = 'googtrans' + exp;
    if (domain) {
      document.cookie = 'googtrans' + exp + ' domain=' + domain + ';';
      document.cookie = 'googtrans' + exp + ' domain=.' + domain + ';';
    }
    // Also overwrite with /auto/en and /en/en
    document.cookie = 'googtrans=/auto/en; path=/;';
    document.cookie = 'googtrans=/en/en; path=/;';

    var select = document.querySelector('.goog-te-combo');
    if (select) {
      select.value = '';
      select.dispatchEvent(new Event('change', { bubbles: true }));
      select.dispatchEvent(new Event('input', { bubbles: true }));
    }
    setTimeout(function() {
      window.location.reload();
    }, 350);
    return;
  }

  showToast('Translating to ' + name + '...');

  // Set googtrans cookie so translations persist across all pages
  var transVal = '/auto/' + code;
  document.cookie = 'googtrans=' + transVal + '; path=/;';
  document.cookie = 'googtrans=/en/' + code + '; path=/;';
  if (domain && domain.indexOf('.') !== -1) {
    document.cookie = 'googtrans=' + transVal + '; domain=' + domain + '; path=/;';
    document.cookie = 'googtrans=' + transVal + '; domain=.' + domain + '; path=/;';
    document.cookie = 'googtrans=/en/' + code + '; domain=' + domain + '; path=/;';
    document.cookie = 'googtrans=/en/' + code + '; domain=.' + domain + '; path=/;';
  }

  function triggerTranslate() {
    var select = document.querySelector('.goog-te-combo');
    if (select) {
      select.value = code;
      select.dispatchEvent(new Event('change', { bubbles: true }));
      select.dispatchEvent(new Event('input', { bubbles: true }));
      return true;
    }
    return false;
  }

  if (!triggerTranslate()) {
    // Poll up to 3 seconds waiting for Google Translate combo to be ready
    var attempts = 0;
    var timer = setInterval(function() {
      attempts++;
      if (triggerTranslate() || attempts >= 30) {
        clearInterval(timer);
        if (attempts >= 30) {
          // If combo not ready after 3s, reload page so cookie takes effect
          window.location.reload();
        }
      }
    }, 100);
  }
}

function syncLanguageUI() {
  try {
    var m = document.cookie.match(/(?:^|;\s*)googtrans=([^;]+)/);
    var langCode = 'en';
    if (m) {
      var parts = decodeURIComponent(m[1]).split('/');
      if (parts.length > 2 && parts[2]) {
        langCode = parts[2].toLowerCase();
      }
    }
    var name = BZN_LANG_NAMES[langCode] || 'English';
    var cur = document.getElementById('bznCurrentLang');
    if (cur) cur.textContent = name;

    var items = document.querySelectorAll('.bzn-lang-item');
    items.forEach(function(item) {
      var onclickAttr = item.getAttribute('onclick') || '';
      var isTarget = (onclickAttr.indexOf('"' + langCode + '"') !== -1 || onclickAttr.indexOf("'" + langCode + "'") !== -1);
      if (isTarget) {
        item.classList.add('selected');
        if (!item.querySelector('.material-symbols-outlined')) {
          var chk = document.createElement('span');
          chk.className = 'material-symbols-outlined notranslate';
          chk.setAttribute('translate', 'no');
          chk.textContent = 'check';
          item.appendChild(chk);
        }
      } else {
        item.classList.remove('selected');
        var chk = item.querySelector('.material-symbols-outlined');
        if (chk) chk.remove();
      }
    });
  } catch(e) {}
}

function protectIconsFromTranslation() {
  try {
    var icons = document.querySelectorAll('.material-symbols-outlined');
    for (var i = 0; i < icons.length; i++) {
      if (!icons[i].classList.contains('notranslate')) {
        icons[i].classList.add('notranslate');
        icons[i].setAttribute('translate', 'no');
      }
    }
  } catch(e) {}
}

// Global Google Translate Init Callback
window.googleTranslateElementInit = function() {
  try {
    new google.translate.TranslateElement({
      pageLanguage: 'en',
      includedLanguages: 'en,hi,mr,gu,bn,ta,te,kn,ml,ar,ja,ko',
      autoDisplay: false
    }, 'google_translate_element');
    protectIconsFromTranslation();
  } catch(e) {}
};

// Protect icons dynamically whenever DOM updates
if (window.MutationObserver) {
  var iconObserver = new MutationObserver(function(mutations) {
    protectIconsFromTranslation();
  });
  document.addEventListener('DOMContentLoaded', function() {
    iconObserver.observe(document.body, { childList: true, subtree: true });
    protectIconsFromTranslation();
    syncLanguageUI();
  });
} else {
  document.addEventListener('DOMContentLoaded', function() {
    protectIconsFromTranslation();
    syncLanguageUI();
  });
}


/* 7. Reading Tools Settings & Distraction-Free Reader Mode */
function applyReadingStyles() {
  try {
    var f = localStorage.getItem('bzn_reading_font') || 'var(--font-body)';
    var s = localStorage.getItem('bzn_reading_size') || '18px';
    var w = localStorage.getItem('bzn_reading_width') || '760px';
    document.documentElement.style.setProperty('--article-reading-font', f);
    document.documentElement.style.setProperty('--article-reading-size', s);
    document.documentElement.style.setProperty('--article-reading-width', w);
    var content = document.getElementById('articleBodyContent');
    if (content) {
      content.style.fontFamily = f;
      content.style.fontSize = s;
      content.style.maxWidth = w;
    }
  } catch(e) {}
}

