/* 8. Toast Notifications (Screen 25) */
function showToast(msg) {
  var c = document.getElementById('bznToastContainer');
  if (!c) return;
  var t = document.createElement('div');
  t.className = 'bzn-toast';
  t.innerHTML = '<span class="material-symbols-outlined" style="font-size:18px;color:#10b981;">check_circle</span><span>' + msg + '</span>';
  c.appendChild(t);
  setTimeout(function() {
    t.style.opacity = '0';
    t.style.transform = 'translateY(10px)';
    setTimeout(function() { t.remove(); }, 300);
  }, 3000);
}

/* 9. Bookmarks & Saved Stories Suite */
function toggleBookmark(btn) {
  var title = btn.getAttribute('data-title') || document.title;
  var url = btn.getAttribute('data-url') || window.location.href;
  var saved = JSON.parse(localStorage.getItem('bzn_saved_stories') || '[]');
  var existingIdx = saved.findIndex(function(s) { return s.url === url; });

  if (existingIdx !== -1) {
    saved.splice(existingIdx, 1);
    localStorage.setItem('bzn_saved_stories', JSON.stringify(saved));
    showToast('Removed from Saved Stories');
  } else {
    saved.push({
      title: title,
      url: url,
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    });
    localStorage.setItem('bzn_saved_stories', JSON.stringify(saved));
    showToast('Story saved to your reading list');
  }
  syncAllBookmarkButtons();
  updateBookmarksBadge();
  renderBookmarksList();
}

function syncAllBookmarkButtons() {
  try {
    var saved = JSON.parse(localStorage.getItem('bzn_saved_stories') || '[]');
    var btns = document.querySelectorAll('[data-url][onclick*="toggleBookmark"], .bzn-bookmark-trigger');
    for (var i = 0; i < btns.length; i++) {
      var u = btns[i].getAttribute('data-url') || window.location.href;
      var isSaved = saved.some(function(x) { return x.url === u; });
      if (isSaved) {
        btns[i].classList.add('saved');
        var icon = btns[i].querySelector('.material-symbols-outlined');
        if (icon) icon.textContent = 'bookmark';
      } else {
        btns[i].classList.remove('saved');
        var icon = btns[i].querySelector('.material-symbols-outlined');
        if (icon) icon.textContent = 'bookmark_border';
      }
    }
  } catch (e) {}
}

function updateBookmarksBadge() {
  try {
    var saved = JSON.parse(localStorage.getItem('bzn_saved_stories') || '[]');
    var count = saved.length;
    var hdrBadge = document.getElementById('bznBookmarksCount');
    if (hdrBadge) {
      hdrBadge.textContent = count;
      hdrBadge.style.display = count > 0 ? 'inline-block' : 'none';
    }
    var drwBadge = document.getElementById('bznDrawerBookmarksCount');
    if (drwBadge) {
      drwBadge.textContent = count;
      drwBadge.style.display = count > 0 ? 'inline-block' : 'none';
    }
    var modalBadge = document.getElementById('bznModalBookmarksCount');
    if (modalBadge) {
      modalBadge.textContent = count;
    }
  } catch(e) {}
}

function openBookmarksModal() {
  var m = document.getElementById('bznBookmarksModal');
  if (m) {
    m.classList.add('open');
    renderBookmarksList();
  }
}

function closeBookmarksModal() {
  var m = document.getElementById('bznBookmarksModal');
  if (m) m.classList.remove('open');
}

document.addEventListener('click', function(e) {
  var btn = e.target.closest('.bzn-remove-bm');
  if (btn) {
    var u = btn.getAttribute('data-remove-url');
    if (u) removeSingleBookmark(u);
  }
});

function renderBookmarksList() {
  var container = document.getElementById('bznBookmarksListContainer');
  if (!container) return;
  var saved = JSON.parse(localStorage.getItem('bzn_saved_stories') || '[]');
  if (saved.length === 0) {
    container.innerHTML = '<div class="bzn-bookmarks-empty"><span class="material-symbols-outlined" style="font-size:42px;color:var(--text-muted);display:block;margin:0 auto 10px auto;">bookmark_border</span><h4 style="font-family:var(--font-heading);font-size:16px;color:var(--text-primary);margin-bottom:6px;">No Saved Stories Yet</h4><p style="font-size:13px;color:var(--text-secondary);margin:0;">Bookmark articles while browsing to read them offline or whenever you have time.</p></div>';
    return;
  }
  var html = '';
  for (var i = saved.length - 1; i >= 0; i--) {
    var s = saved[i];
    html += '<div class="bzn-saved-item">';
    html += '  <div class="bzn-saved-info">';
    html += '    <a class="bzn-saved-title" href="' + s.url + '">' + s.title + '</a>';
    html += '    <span class="bzn-saved-date">Saved on ' + s.date + '</span>';
    html += '  </div>';
    html += '  <div class="bzn-saved-actions">';
    html += '    <a class="bzn-btn-primary" href="' + s.url + '" style="font-size:12px;padding:6px 12px;height:auto;text-decoration:none;">Read</a>';
    html += '   <button class="bzn-icon-btn bzn-remove-bm" data-remove-url="' + encodeURIComponent(s.url) + '" style="width:32px;height:32px;" title="Remove" type="button">style="width:32px;height:32px;" title="Remove" type="button">';
    html += '      <span class="material-symbols-outlined" style="font-size:16px;">delete</span>';
    html += '    </button>';
    html += '  </div>';
    html += '</div>';
  }
  container.innerHTML = html;
}

function removeSingleBookmark(url) {
  var saved = JSON.parse(localStorage.getItem('bzn_saved_stories') || '[]');
  var dec = decodeURIComponent(url);
  saved = saved.filter(function(s) { return s.url !== url && s.url !== dec; });
  localStorage.setItem('bzn_saved_stories', JSON.stringify(saved));
  syncAllBookmarkButtons();
  updateBookmarksBadge();
  renderBookmarksList();
  showToast('Removed from saved list');
}

function clearAllBookmarks() {
  if (confirm('Clear all saved stories?')) {
    localStorage.removeItem('bzn_saved_stories');
    syncAllBookmarkButtons();
    updateBookmarksBadge();
    renderBookmarksList();
    showToast('All saved stories cleared');
  }
}

