/* 12. Interactive Web Speech API Player (Screens 07 & 10) */
var audioSynth = window.speechSynthesis;
var audioUtterance = null;
var isAudioPlaying = false;
var audioChunks = [];
var currentChunkIdx = 0;
var audioRate = 1.0;

function initAudioContent() {
  var body = document.getElementById('articleBodyContent');
  if (!body) return;
  var text = body.innerText || body.textContent;
  audioChunks = text.match(/[^.!?]+[.!?]+/g) || [text];
  currentChunkIdx = 0;
}

function toggleVoice() {
  if (!audioSynth) {
    showToast('Audio narration not supported in this browser.');
    return;
  }
  if (isAudioPlaying) {
    pauseVoice();
  } else {
    playVoice();
  }
}

function playVoice() {
  if (audioChunks.length === 0) initAudioContent();
  if (audioSynth.paused) {
    audioSynth.resume();
    isAudioPlaying = true;
    updateAudioUI(true);
    return;
  }
  audioSynth.cancel();
  isAudioPlaying = true;
  updateAudioUI(true);
  speakNextChunk();
}

function pauseVoice() {
  if (audioSynth) audioSynth.pause();
  isAudioPlaying = false;
  updateAudioUI(false);
}

function stopVoice() {
  if (audioSynth) audioSynth.cancel();
  isAudioPlaying = false;
  currentChunkIdx = 0;
  updateAudioUI(false);
  updateAudioProgress(0);
}

function speakNextChunk() {
  if (currentChunkIdx >= audioChunks.length) {
    stopVoice();
    showToast('Narration finished.');
    return;
  }
  var chunk = audioChunks[currentChunkIdx];
  audioUtterance = new SpeechSynthesisUtterance(chunk);
  audioUtterance.rate = audioRate;

  audioUtterance.onend = function() {
    currentChunkIdx++;
    var pct = Math.round((currentChunkIdx / audioChunks.length) * 100);
    updateAudioProgress(pct);
    if (isAudioPlaying) speakNextChunk();
  };

  audioUtterance.onerror = function() {
    currentChunkIdx++;
    if (isAudioPlaying) speakNextChunk();
  };

  audioSynth.speak(audioUtterance);
}

function setVoiceSpeed(rate, btn) {
  audioRate = rate;
  document.querySelectorAll('.bzn-speed-btn').forEach(function(b) {
    if (b.textContent === rate.toFixed(1) + 'x' || b.textContent === rate + 'x') {
      b.classList.add('active');
    } else {
      b.classList.remove('active');
    }
  });
  if (isAudioPlaying) {
    audioSynth.cancel();
    speakNextChunk();
  }
}

function updateAudioUI(playing) {
  var mainIcon = document.getElementById('audioPlayIcon');
  if (mainIcon) mainIcon.textContent = playing ? 'pause' : 'play_arrow';
  var stickyIcon = document.getElementById('stickyAudioPlayIcon');
  if (stickyIcon) stickyIcon.textContent = playing ? 'pause' : 'play_arrow';
  var toolbarIcon = document.getElementById('audioToolbarIcon');
  if (toolbarIcon) toolbarIcon.textContent = playing ? 'pause' : 'volume_up';
}

function updateAudioProgress(pct) {
  var p = document.getElementById('audioProgress');
  if (p) p.style.width = pct + '%';
  var sp = document.getElementById('stickyAudioProgress');
  if (sp) sp.style.width = pct + '%';
}

function seekAudioBar(e) {
  if (audioChunks.length === 0) initAudioContent();
  var bar = e.currentTarget;
  var rect = bar.getBoundingClientRect();
  var clickX = e.clientX - rect.left;
  var pct = Math.max(0, Math.min(1, clickX / rect.width));
  currentChunkIdx = Math.floor(pct * audioChunks.length);
  updateAudioProgress(Math.round(pct * 100));
  if (isAudioPlaying) {
    audioSynth.cancel();
    speakNextChunk();
  }
}

function closeStickyAudioBar() {
  var bar = document.getElementById('bznStickyAudioBar');
  if (bar) bar.classList.remove('visible');
}

window.addEventListener('beforeunload', function() {
  if (audioSynth) audioSynth.cancel();
});

window.addEventListener('scroll', function() {
  var heroAudio = document.getElementById('bznHeroAudioPlayer');
  var stickyAudio = document.getElementById('bznStickyAudioBar');
  if (heroAudio && stickyAudio) {
    var rect = heroAudio.getBoundingClientRect();
    if (rect.bottom < 0) {
      stickyAudio.classList.add('visible');
    } else {
      stickyAudio.classList.remove('visible');
    }
  }
}, { passive: true });

