/* 16. Dynamic Navigation Highlighter & Channel Subcategory Engine */
(function() {
  function initNavAndChannels() {
    var rawPath = location.pathname;
    var path = decodeURIComponent(rawPath).toLowerCase();
    var isHome = (path === '' || path === '/' || path === '/index.html');

    // 1. Precise Header Navigation Highlighting
    var desktopLinks = document.querySelectorAll('.bzn-nav-desktop .bzn-nav-item');
    var matchedDesktop = false;

    desktopLinks.forEach(function(link) {
      link.classList.remove('active');
      var href = (link.getAttribute('href') || '').toLowerCase();
      var cleanHref = decodeURIComponent(href.split('?')[0]);

      if (!isHome && cleanHref !== '/' && cleanHref !== '') {
        if (path === cleanHref || path.indexOf(cleanHref) === 0 || cleanHref.indexOf(path) === 0) {
          link.classList.add('active');
          matchedDesktop = true;
        }
      }
    });

    if (isHome || !matchedDesktop) {
      var homeLink = document.querySelector('.bzn-nav-desktop .bzn-nav-item[href="/"], .bzn-nav-desktop a:first-child');
      if (isHome && homeLink) homeLink.classList.add('active');
    }

    // 2. Mobile Drawer Highlighting
    var drawerLinks = document.querySelectorAll('.bzn-drawer-links a');
    drawerLinks.forEach(function(link) {
      link.classList.remove('active');
      var href = (link.getAttribute('href') || '').toLowerCase();
      var cleanHref = decodeURIComponent(href.split('?')[0]);
      if (isHome && (cleanHref === '/' || cleanHref === '')) {
        link.classList.add('active');
      } else if (!isHome && cleanHref !== '/' && path.indexOf(cleanHref) !== -1) {
        link.classList.add('active');
      }
    });

    // 3. Footer Links Highlighting
    var footerLinks = document.querySelectorAll('.bzn-footer-links a');
    footerLinks.forEach(function(link) {
      link.classList.remove('active');
      var href = (link.getAttribute('href') || '').toLowerCase();
      var cleanHref = decodeURIComponent(href.split('?')[0]);
      if (!isHome && cleanHref !== '/' && path.indexOf(cleanHref) !== -1) {
        link.classList.add('active');
      }
    });

    // 4. Channel-Specific Subtitle & Filter Pills Engine
    var pillsContainer = document.getElementById('bznFilterPills');
    var subtitleEl = document.getElementById('bznCategorySubtitle');
    var titleEl = document.getElementById('bznCategoryTitle');

    // Channel configurations matching master blueprint & live blog labels
    var channelConfigs = {
      'business': {
        title: 'Business',
        subtitle: 'Curated financial intelligence, stock market movements, economic policy, investing insights and corporate trends.',
        pills: [
          { name: 'All', url: '/search/label/Business' },
          { name: 'Stocks', url: '/search/label/Stocks' },
          { name: 'Stock Market', url: '/search/label/Stock%20Market' },
          { name: 'Investing', url: '/search/label/Investing' },
          { name: 'Economy', url: '/search/label/Economy' },
          { name: 'Finance', url: '/search/label/Finance' },
          { name: 'Nifty', url: '/search/label/Nifty' }
        ],
        fallbackTags: ['Stock Market', 'Stocks', 'Investing', 'Economy', 'Finance']
      },
      'tech': {
        title: 'Tech & AI',
        subtitle: 'Latest technology breakthroughs, artificial intelligence updates, smartphones, gadgets, and futuristic computing.',
        pills: [
          { name: 'All', url: '/search/label/Tech%20%26%20AI' },
          { name: 'AI', url: '/search/label/AI' },
          { name: 'Technology', url: '/search/label/Technology' },
          { name: 'Gadgets', url: '/search/label/gadgets' },
          { name: 'Smartphones', url: '/search/label/Smartphones' },
          { name: 'Software', url: '/search/label/Software' },
          { name: 'Space Tech', url: '/search/label/Space%20Tech' }
        ],
        fallbackTags: ['Tech & AI', 'Technology', 'AI', 'gadgets']
      },
      'science': {
        title: 'Science',
        subtitle: 'Frontier discoveries in deep space, astrophysics, NASA missions, SpaceX, planetary science, and human exploration.',
        pills: [
          { name: 'All', url: '/search/label/Science' },
          { name: 'Space', url: '/search/label/Space' },
          { name: 'NASA', url: '/search/label/NASA' },
          { name: 'SpaceX', url: '/search/label/SpaceX' },
          { name: 'Mars', url: '/search/label/Mars' },
          { name: 'Materials Science', url: '/search/label/materials%20science' }
        ],
        fallbackTags: ['Science', 'Space', 'NASA']
      },
      'sports': {
        title: 'Sports',
        subtitle: 'Live match scores, cricket tournaments, T20 World Cup action, football leagues, and athletic milestones.',
        pills: [
          { name: 'All', url: '/search/label/Sports' },
          { name: 'Cricket', url: '/search/label/cricket' },
          { name: 'T20', url: '/search/label/T20' },
          { name: 'World Cup', url: '/search/label/World%20Cup' },
          { name: 'Football', url: '/search/label/Real%20Madrid' },
          { name: 'Indian Athletics', url: '/search/label/Indian%20Athletics' }
        ],
        fallbackTags: ['Sports', 'cricket', 'T20']
      },
      'trending': {
        title: 'Trending',
        subtitle: 'Everything capturing viral attention, high discourse, breaking updates, and web sensations right now.',
        pills: [
          { name: 'All', url: '/search/label/Trending' },
          { name: 'Viral News', url: '/search/label/Viral%20News' },
          { name: 'Trending Now', url: '/search/label/trending' },
          { name: 'Hot Topics', url: '/search/label/viral' },
          { name: 'Breaking', url: '/search/label/Breaking' }
        ],
        fallbackTags: ['Trending', 'trending', 'viral', 'Viral News']
      }
    };

    // Detect active channel from path
    var activeKey = null;
    if (path.indexOf('/label/business') !== -1 || path.indexOf('/label/stock') !== -1 || path.indexOf('/label/invest') !== -1 || path.indexOf('/label/econom') !== -1) {
      activeKey = 'business';
    } else if (path.indexOf('/label/tech') !== -1 || path.indexOf('/label/ai') !== -1 || path.indexOf('/label/gadget') !== -1) {
      activeKey = 'tech';
    } else if (path.indexOf('/label/science') !== -1 || path.indexOf('/label/space') !== -1 || path.indexOf('/label/nasa') !== -1) {
      activeKey = 'science';
    } else if (path.indexOf('/label/sport') !== -1 || path.indexOf('/label/cricket') !== -1) {
      activeKey = 'sports';
    } else if (path.indexOf('/label/trending') !== -1 || path.indexOf('/label/viral') !== -1) {
      activeKey = 'trending';
    }

    if (activeKey && channelConfigs[activeKey]) {
      var cfg = channelConfigs[activeKey];
      if (subtitleEl) subtitleEl.textContent = cfg.subtitle;

      if (pillsContainer) {
        var pillsHtml = '';
        cfg.pills.forEach(function(pill) {
          var pillPath = decodeURIComponent(pill.url.split('?')[0]).toLowerCase();
          var isPillActive = (path === pillPath || (path.indexOf(pillPath) !== -1 && pillPath.length > 10));
          pillsHtml += '<a class="bzn-filter-pill' + (isPillActive ? ' active' : '') + '" href="' + pill.url + '">' + pill.name + '</a>';
        });
        pillsContainer.innerHTML = pillsHtml;
      }
    }

    // 5. Smart Empty State Resolver
    var grid = document.getElementById('bznCategoryGrid');
    var empty = document.getElementById('bznEmptyState');

    if (grid && empty && !grid.querySelector('.bzn-card')) {
      // If Blogger returned 0 posts for this label (e.g. Business), check for smart feed fallback
      if (activeKey && channelConfigs[activeKey]) {
        var fallbackTag = channelConfigs[activeKey].fallbackTags[0] || 'Stock Market';
        var feedUrl = '/feeds/posts/default/-/' + encodeURIComponent(fallbackTag) + '?alt=json&max-results=8';

        fetch(feedUrl)
          .then(function(res) { return res.json(); })
          .then(function(data) {
            var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
            if (entries.length > 0) {
              var cardsHtml = '';
              entries.forEach(function(entry) {
                var title = entry.title ? entry.title.$t : 'Untitled Dispatch';
                var postUrl = '#';
                if (entry.link) {
                  for (var k = 0; k < entry.link.length; k++) {
                    if (entry.link[k].rel === 'alternate') {
                      postUrl = entry.link[k].href;
                      break;
                    }
                  }
                }
                var thumb = '';
                if (entry.media$thumbnail) {
                  thumb = entry.media$thumbnail.url.replace('/s72-c/', '/w640-h360-p-k-no-nu/');
                } else if (entry.content && entry.content.$t) {
                  var m = entry.content.$t.match(/<img[^>]+src=['"]([^'"]+)['"]/);
                  if (m) thumb = m[1];
                }
                var pubDate = entry.published ? new Date(entry.published.$t).toLocaleDateString() : '';
                var categoryName = entry.category && entry.category[0] ? entry.category[0].term : fallbackTag;

                cardsHtml += '<article class="bzn-card">';
                cardsHtml += '  <div class="bzn-card-thumb-wrap">';
                if (thumb) {
                  cardsHtml += '    <a href="' + postUrl + '"><img class="bzn-card-thumb" alt="' + title + '" src="' + thumb + '"/></a>';
                } else {
                  cardsHtml += '    <div class="bzn-card-thumb-placeholder"><span class="material-symbols-outlined" style="font-size:36px;">image</span></div>';
                }
                cardsHtml += '  </div>';
                cardsHtml += '  <div class="bzn-card-body">';
                cardsHtml += '    <div class="bzn-card-pill-row"><span class="bzn-pill-badge">' + categoryName + '</span></div>';
                cardsHtml += '    <h3 class="bzn-card-title"><a href="' + postUrl + '">' + title + '</a></h3>';
                cardsHtml += '    <div class="bzn-card-meta">';
                cardsHtml += '      <span>' + pubDate + '</span>';
                cardsHtml += '      <button class="bzn-icon-btn" data-title="' + title + '" data-url="' + postUrl + '" onclick="toggleBookmark(this)" style="width:28px;height:28px;" title="Save Story" type="button">';
                cardsHtml += '        <span class="material-symbols-outlined" style="font-size:16px;">bookmark_border</span>';
                cardsHtml += '      </button>';
                cardsHtml += '    </div>';
                cardsHtml += '  </div>';
                cardsHtml += '</article>';
              });

              grid.innerHTML = cardsHtml;
              grid.style.display = 'grid';
              empty.hidden = true;
            } else {
              grid.style.display = 'none';
              empty.hidden = false;
            }
          })
          .catch(function(err) {
            grid.style.display = 'none';
            empty.hidden = false;
          });
      } else {
        grid.style.display = 'none';
        empty.hidden = false;
      }
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initNavAndChannels);
  } else {
    initNavAndChannels();
  }
})();


/* 13. Back to top */
function scrollToTop() { window.scrollTo({ top: 0, behavior: 'smooth' }); }
window.addEventListener('scroll', function() {
  var b = document.getElementById('bznBackTop');
  if (b) b.classList.toggle('show', (window.pageYOffset || document.documentElement.scrollTop) > 400);
}, { passive: true });

/* 14. Category pill colours */
(function() {
  function paint() {
    var pills = document.querySelectorAll('.bzn-pill-badge');
    for (var i = 0; i < pills.length; i++) {
      var n = (pills[i].textContent || '').toLowerCase();
      var c = '';
      if (/science|space|nasa|health/.test(n)) c = 'is-sci';
      else if (/business|market|stock|ipo|econom|finance/.test(n)) c = 'is-biz';
      else if (/sport|cricket|football|gaming/.test(n)) c = 'is-sport';
      else if (/viral|trending|breaking/.test(n)) c = 'is-hot';
      if (c) pills[i].classList.add(c);
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', paint); else paint();
})();

/* 15. Restore saved reading preferences + bookmark state */
(function() {
  function restore() {
    var body = document.getElementById('articleBodyContent');
    if (body) {
      var f = localStorage.getItem('bzn_reading_font'), s = localStorage.getItem('bzn_reading_size'), w = localStorage.getItem('bzn_reading_width');
      if (f) body.style.fontFamily = f;
      if (s) body.style.fontSize = s;
      if (w) body.style.maxWidth = w;
    }
    try {
      var saved = JSON.parse(localStorage.getItem('bzn_saved_stories') || '[]');
      var btns = document.querySelectorAll('[data-url][onclick*="toggleBookmark"]');
      for (var i = 0; i < btns.length; i++) {
        var u = btns[i].getAttribute('data-url');
        if (saved.some(function(x) { return x.url === u; })) {
          btns[i].classList.add('saved');
          var ic = btns[i].querySelector('.material-symbols-outlined');
          if (ic) ic.textContent = 'bookmark';
        }
      }
    } catch (e) {}
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', restore); else restore();
})();

